package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.NavigateMenuRequest;
import com.bank.payments.adapters.in.rest.NavigateMenuResponse;
import com.bank.payments.domain.error.BusinessError;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * Oracle for NavigateMenu (legacy PAGOMNU, paragraph 2000-ELEGIR-OPCION, EVALUATE OPCIONI).
 * Pins RULE-006.
 */
class NavigateMenuServiceTest {

    private final NavigateMenuService service = new NavigateMenuService();

    private void assertInvalidOption(String option) {
        assertThatThrownBy(() -> service.execute(new NavigateMenuRequest(option)))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    BusinessError error = (BusinessError) e;
                    assertThat(error.code()).isEqualTo("INVALID_OPTION");
                    assertThat(error.legacyCode()).isEqualTo("OTHER");
                    assertThat(error.getMessage()).isEqualTo("OPCION NO VALIDA");
                });
    }

    // RULE-006: WHEN '1' -> XCTL PROGRAM('PAGOORD')
    @Test
    void user_selects_payment_order_entry() {
        NavigateMenuResponse response = service.execute(new NavigateMenuRequest("1"));

