package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.NavigateMenuRequest;
import com.bank.payments.adapters.in.rest.NavigateMenuResponse;
import com.bank.payments.domain.error.BusinessError;

/**
 * NavigateMenu (legacy PAGOMNU, paragraph 2000-ELEGIR-OPCION, EVALUATE OPCIONI). RULE-006.
 *
 * Option '1' routes to PAGOORD (XCTL). Option '9' performs 9000-TERMINAR (session end): the
 * source gives no destination program for it, so the destination is left null and the
 * message is not set (MENSAJEO is only set in the OTHER branch). Any other value is rejected
 * with 'OPCION NO VALIDA'.
 */
public class NavigateMenuService {

    public NavigateMenuService() {
    }

    public NavigateMenuResponse execute(NavigateMenuRequest request) {
        String option = request == null ? null : request.option();

        if ("1".equals(option)) {
            // WHEN '1' -> XCTL PROGRAM('PAGOORD')
            return new NavigateMenuResponse("PAGOORD", null);
        }
        if ("9".equals(option)) {
            // WHEN '9' -> PERFORM 9000-TERMINAR (no destination program, no message)
            return new NavigateMenuResponse(null, null);
        }
        // WHEN OTHER -> MOVE 'OPCION NO VALIDA' TO MENSAJEO
        throw new BusinessError("INVALID_OPTION", "OTHER", "OPCION NO VALIDA");
    }
